package com.novabank.risk.config;
import io.jsonwebtoken.Jwts; import io.jsonwebtoken.security.Keys; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.http.HttpHeaders; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.stereotype.Component; import org.springframework.util.StringUtils; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.nio.charset.StandardCharsets; import java.util.List;
@Configuration @EnableMethodSecurity public class SecurityConfig {
 @Bean SecurityFilterChain chain(HttpSecurity h,JwtFilter f)throws Exception{return h.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/actuator/health/**","/actuator/info","/actuator/prometheus").permitAll().requestMatchers("/api/risk/internal/**").hasRole("INTERNAL").requestMatchers("/api/risk/**").hasAnyRole("FRAUD_ANALYST","OPERATIONS_ADMIN","SUPPORT_AGENT").anyRequest().denyAll()).addFilterBefore(f,UsernamePasswordAuthenticationFilter.class).build();}
}
@Component class JwtFilter extends OncePerRequestFilter {private final byte[] secret;private final String issuer; JwtFilter(@Value("${novabank.jwt.secret}")String s,@Value("${novabank.jwt.issuer}")String i){secret=s.getBytes(StandardCharsets.UTF_8);issuer=i;}
 protected void doFilterInternal(HttpServletRequest q,HttpServletResponse p,FilterChain c)throws ServletException,IOException{var h=q.getHeader(HttpHeaders.AUTHORIZATION);if(StringUtils.hasText(h)&&h.startsWith("Bearer "))try{var x=Jwts.parser().verifyWith(Keys.hmacShaKeyFor(secret)).requireIssuer(issuer).build().parseSignedClaims(h.substring(7)).getPayload();var role=x.get("role",String.class);String authority=Boolean.TRUE.equals(x.get("internal",Boolean.class))?"ROLE_INTERNAL":role!=null&&role.startsWith("ROLE_")?role:"ROLE_"+(role==null?"CUSTOMER":role);SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(x.getSubject(),null,List.of(new SimpleGrantedAuthority(authority))));}catch(RuntimeException e){SecurityContextHolder.clearContext();}c.doFilter(q,p);}}
